let lang = 'de'
export const languages = () => Object.keys(dict)
export const getLang = () => lang
export function setLang(l) { lang = dict[l] ? l : 'de'; document.documentElement.lang = lang }
export function detectLang() {
  const saved = (() => { try { return localStorage.getItem('rp.lang') } catch { return null } })()
  if (saved && dict[saved]) return saved
  const nav = (navigator.language || 'de').slice(0, 2)
  return dict[nav] ? nav : 'en'
}
export function t(key, vars = {}) {
  const s = dict[lang][key] ?? dict.en[key] ?? key
  return s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '')
}
